 function analysisLayers(){const facade=result?.sampling==='facade-grid-v1';$('#solar-grid-display').hidden=!facade;if(map)map.material.visible=!facade||$('#solar-show-points').checked;if(cellMesh)cellMesh.visible=$('#solar-show-cells').checked;if(gridMesh)gridMesh.visible=$('#solar-show-grid').checked;}
 for(const id of ['cells','points','grid'])$('#solar-show-'+id).onchange=analysisLayers;
 function applyPresentation(){const root=getDisplayModel();if(root){root.visible=display.show;root.traverse(o=>{if(!o.material)return;for(const m of (Array.isArray(o.material)?o.material:[o.material])){if(!originalMaterials.has(m))originalMaterials.set(m,{color:m.color?.clone(),opacity:m.opacity,transparent:m.transparent,depthWrite:m.depthWrite});const old=originalMaterials.get(m);if(m.color&&old.color)m.color.copy(result&&display.neutral?new THREE.Color(o.isMesh?0xb9b9b5:0x858582):old.color);m.opacity=old.opacity*display.opacity;m.transparent=old.transparent||display.opacity<1;m.depthWrite=old.depthWrite&&display.opacity===1;m.needsUpdate=true;}});}scene.background.copy(result&&display.neutral?new THREE.Color(0xf0f0ed):originalBackground);}
 function isSky(){return ['daylight','sky'].includes(result?.settings.analysis);}
 function resultTitle(){return result.settings.analysis==='daylight'?'Façade VSC (%)':result.settings.analysis==='sky'?'Horizontal sky-view factor (%)':result.weather?'Estimated irradiation (kWh/m²)':'Direct sunlight hours';}
 function unit(){return isSky()?'%':result?.weather?'kWh/m²':'h';}
 function scaleMaximum(){return isSky()?(result.settings.analysis==='daylight'?40:100):result?.weather?Math.max(.1,Math.min(100,+$('#radiation-scale-max').value||10)):result.daylight;}
 function pointText(){let text=sampleDescription(selected,result.samples[selected],result.values[selected],isSky()?'% '+(result.settings.analysis==='daylight'?'VSC':'sky-view factor'):result.weather?'kWh/m²':'h direct sun');if(result.sampling==='facade-grid-v1'){const s=result.samples[selected];text+='\nGrid row '+s.gridRow+' · column '+s.gridColumn+' · face triangle '+s.faceTriangle;}if(isSky()){const c=result.components[selected];text+='\nVisible sky (solid angle): '+c.visibleSky.toFixed(2)+'%';if(result.settings.analysis==='daylight')text+='\nHorizontal sky-view factor: '+c.skyView.toFixed(2)+'%';}if(result.weather){const c=result.components[selected];text+='\nDirect '+c.direct.toFixed(4)+' · diffuse '+c.diffuse.toFixed(4)+' kWh/m²';}return text;}
 $('#radiation-scale-max').oninput=()=>recolor();
