   if(snapshot.analysis==='daylight'&&snapshot.target!=='facade')throw Error('Select façades for VSC.');let samples,gridLines=[],cellPositions=[],cellSamples=[];if(snapshot.target==='ground'){samples=[];for(let x=0;x<25;x++)for(let z=0;z<25;z++)samples.push({position:[-snapshot.extent+(x+.5)*snapshot.extent*2/25,.04,-snapshot.extent+(z+.5)*snapshot.extent*2/25],normal:[0,1,0]});}else if(snapshot.target==='facade'){const grid=facadeGrid(own,snapshot.gridWidth,snapshot.gridHeight);samples=grid.samples;gridLines=grid.lines;cellPositions=grid.cellPositions;cellSamples=grid.cellSamples;}else samples=sampleSurfaces(roofSurfaceTriangles(own,project),snapshot.target);
